const DEFAULT={version:3,name:'Фабрика процессов · VENIO-C',mode:'demo',nodes:INITIAL_NODES,edges:INITIAL_EDGES,settings:{target:10,releaseUnits:12,shiftMinutes:20,taktSeconds:120,productionBatch:2,transportBatch:2,initialStock:2,initialFlowWip:2,partialTransport:false,logistCount:1,handlingSeconds:7,speed:1.1,returnMultiplier:1.7,metersPerPixel:0.02,layoutLogistics:true,seed:2026,materialCost:15000,salePrice:70000,wageHour:400,logistWageHour:420,equipmentShift:2000,rentShift:1100,overheadShift:1400},createdAt:'2026-11-21',description:'Учебная фабрика; времена/цены, кроме отдельно подтверждённых, демонстрационные.'};
